// single-item input: one competitor request per run.
const cfg = $('Settings').first().json;
const body = $input.first().json || {};

const task = (body.tasks || [])[0] || {};
if (Number(body.status_code) !== 20000 || Number(task.status_code) !== 20000) {
  throw new Error(
    'DataForSEO refused the competitor lookup: ' +
    (task.status_code || body.status_code) + ' ' +
    String(task.status_message || body.status_message || '').slice(0, 200)
  );
}

const bare = (d) => String(d || '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');

const you = bare(cfg.your_domain);
if (!you) throw new Error('Settings.your_domain is empty.');

// Measured 2026-09-05: competitors_domain for a real domain answered with that
// domain in first place, then youtube.com, reddit.com, linkedin.com,
// medium.com, google.com and quora.com. Every one of those genuinely ranks for
// the same queries and not one of them is a competitor, so a report that names
// them is a report nobody reads twice.
const PLATFORMS = new Set([
  'youtube.com', 'reddit.com', 'linkedin.com', 'medium.com', 'google.com',
  'quora.com', 'facebook.com', 'instagram.com', 'x.com', 'twitter.com',
  'pinterest.com', 'tiktok.com', 'wikipedia.org', 'en.wikipedia.org',
  'amazon.com', 'apple.com', 'microsoft.com', 'github.com', 'substack.com',
]);

const pinned = String(cfg.pinned_rivals || '').split(',').map(bare).filter(Boolean);
const wanted = Math.min(Math.max(Number(cfg.rivals) || 5, 2), 12);

let rivals = [];
if (pinned.length) {
  // A pinned set is the whole answer. Somebody who names their competitors
  // knows the market better than an intersection of ranking keywords does.
  rivals = pinned.filter((d) => d !== you).slice(0, wanted);
} else {
  const items = ((task.result || [])[0] || {}).items || [];
  for (const it of items) {
    const d = bare(it.domain);
    if (!d || d === you || PLATFORMS.has(d)) continue;
    const kw = Number(((it.metrics || {}).organic || {}).count) || 0;
    // A domain sharing three keywords with you is a coincidence, not a rival.
    if (Number(it.intersections) < 3 && kw < 3) continue;
    rivals.push(d);
    if (rivals.length >= wanted) break;
  }
}

if (!rivals.length) {
  throw new Error(
    'No competitors survived the filter. Either the domain has too little ' +
    'organic footprint for the API to find peers, or every peer it found was a ' +
    'platform. Name three or four in Settings.pinned_rivals instead.'
  );
}

const targets = [you, ...rivals];

return [{
  json: {
    you,
    rivals,
    targets,
    picked_by: pinned.length ? 'pinned in Settings' : 'discovered from shared keywords',
    body_traffic: [{
      targets,
      location_name: cfg.location,
      language_name: cfg.language,
    }],
  },
}];

// One item per domain out: the Switch below routes per item, and a single
// object holding an array would take one lane for the whole market.
const cfg = $('Settings').first().json;
const plan = $('Read The Peer Set').first().json;
const body = $('Measure The Whole Set').first().json || {};

const task = (body.tasks || [])[0] || {};
if (Number(body.status_code) !== 20000 || Number(task.status_code) !== 20000) {
  throw new Error(
    'DataForSEO refused the traffic estimate: ' +
    (task.status_code || body.status_code) + ' ' +
    String(task.status_message || body.status_message || '').slice(0, 200)
  );
}

const now = new Map();
for (const it of (((task.result || [])[0] || {}).items || [])) {
  const d = String(it.target || '').toLowerCase();
  const org = (it.metrics || {}).organic || {};
  if (d) now.set(d, { visits: Math.round(Number(org.etv) || 0), keywords: Number(org.count) || 0 });
}

const today = new Date().toISOString().slice(0, 10);

// The history sheet is append-only, so a domain has one row per run. The
// comparison wants the newest row that is not today's - taking the last
// matching row would compare a second run in one morning against itself.
const prior = new Map();
for (const item of $('Read Last Month\'s Numbers').all()) {
  const r = item.json || {};
  const d = String(r.domain || '').toLowerCase();
  if (!d) continue;
  const on = String(r.checked_on || '');
  if (!on || on >= today) continue;
  const held = prior.get(d);
  if (!held || on > String(held.checked_on || '')) prior.set(d, r);
}

const total = plan.targets.reduce((sum, d) => sum + ((now.get(d) || {}).visits || 0), 0);
const moveThreshold = Math.max(Number(cfg.move_pct) || 5, 0.5);

const rows = plan.targets.map((d) => {
  const cur = now.get(d) || { visits: 0, keywords: 0 };
  const share = total ? Math.round((cur.visits / total) * 10000) / 100 : 0;
  const was = prior.get(d);
  const wasShare = was ? Number(was.share_pct) || 0 : 0;
  const delta = was ? Math.round((share - wasShare) * 100) / 100 : 0;

  // Three lanes, decided once here so the Switch only carries the decision out.
  // A domain with no prior row is genuinely new to the set and worth a profile;
  // a rival that took share is worth finding out off which pages; everything
  // else costs nothing more this run.
  let lane = 'steady';
  if (!was) lane = 'new';
  else if (d !== plan.you && delta >= moveThreshold) lane = 'gained';

  return {
    json: {
      checked_on: today,
      domain: d,
      is_you: d === plan.you,
      visits: cur.visits,
      keywords: cur.keywords,
      share_pct: share,
      was_share_pct: wasShare,
      share_delta: delta,
      had_prior: Boolean(was),
      lane,
      body_pages: [{
        target: d,
        location_name: cfg.location,
        language_name: cfg.language,
        limit: 6,
        order_by: ['metrics.organic.etv,desc'],
      }],
      body_profile: [{
        target: d,
        location_name: cfg.location,
        language_name: cfg.language,
      }],
    },
  };
});

return rows;

// The gained lane only. One response per input item, in order - the response
// carries nothing naming the domain, so the pairing is positional and there is
// no other way to do it.
const asked = $('Find What They Published').all();
const rows = $('What Happened To Each One?').all()
  .map((i) => i.json)
  .filter((r) => r.lane === 'gained');

const out = [];
for (let i = 0; i < asked.length; i++) {
  const row = rows[i] || {};
  const body = asked[i].json || {};
  const task = (body.tasks || [])[0] || {};

  // A failed page lookup loses the detail, not the row. The share numbers cost
  // a paid request of their own and are the point of the report.
  let pages = [];
  if (Number(body.status_code) === 20000 && Number(task.status_code) === 20000) {
    pages = (((task.result || [])[0] || {}).items || []).map((it) => ({
      url: String(it.page_address || ''),
      visits: Math.round(Number(((it.metrics || {}).organic || {}).etv) || 0),
    })).filter((p) => p.url).slice(0, 5);
  }

  out.push({ json: { ...row, top_pages: pages, note: '' } });
}

return out;

// The new lane only. Same positional pairing as the winners: domain_rank_overview
// returns se_type, location_code, language_code and metrics - and nothing at all
// naming the domain it describes.
const asked = $('Profile The Newcomer').all();
const rows = $('What Happened To Each One?').all()
  .map((i) => i.json)
  .filter((r) => r.lane === 'new');

const out = [];
for (let i = 0; i < asked.length; i++) {
  const row = rows[i] || {};
  const body = asked[i].json || {};
  const task = (body.tasks || [])[0] || {};

  let note = 'first time in this peer set';
  if (Number(body.status_code) === 20000 && Number(task.status_code) === 20000) {
    const m = (((task.result || [])[0] || {}).items || [])[0] || {};
    const org = (m.metrics || {}).organic || {};
    const up = Number(org.is_up) || 0;
    const down = Number(org.is_down) || 0;
    const isNew = Number(org.is_new) || 0;
    const top10 = (Number(org.pos_1) || 0) + (Number(org.pos_2_3) || 0) + (Number(org.pos_4_10) || 0);
    // Climbing or merely large. A domain with more keywords going down than up
    // is a big site drifting, not a new threat, and the report should say so.
    note = 'first time in this peer set - ' + top10.toLocaleString('en-US') +
      ' keywords in the top ten, ' + isNew.toLocaleString('en-US') + ' new, ' +
      up.toLocaleString('en-US') + ' up against ' + down.toLocaleString('en-US') + ' down';
  }

  out.push({ json: { ...row, top_pages: [], note } });
}

return out;

// Input is the Merge barrier: three lanes appended into one stream. Everything
// is read back off it here, because a lane that routed nothing contributes no
// items at all and reading the lanes by name would then throw.
const plan = $('Read The Peer Set').first().json;

const rows = $input.all().map((i) => i.json).filter((r) => r && r.domain);
// Biggest share first, so the document opens on the market and not on whichever
// lane happened to finish first.
rows.sort((a, b) => b.share_pct - a.share_pct);

return [{
  json: {
    checked_on: rows.length ? rows[0].checked_on : new Date().toISOString().slice(0, 10),
    picked_by: plan.picked_by,
    rows,
  },
}];

// single-item input: one report per run.
const cfg = $('Settings').first().json;
const payload = $('Gather The Lanes').first().json;
const rows = payload.rows || [];
const prose = String(($input.first().json || {}).text || '').trim();

// The Docs insert writes the string it is given. Markdown is not parsed, so a
// heading has to be built out of capitals and line breaks or it arrives on the
// page as the characters ## Heading.
const pad = (s, n) => String(s).padEnd(n, ' ');
const table = rows.map((r) =>
  pad(r.domain.slice(0, 30), 32) +
  pad(r.visits.toLocaleString('en-US'), 14) +
  pad(r.share_pct + '%', 9) +
  // A domain with no earlier row has no change, and printing "0" for that reads
  // as "held its ground" - the opposite of what it means.
  (r.had_prior ? (r.share_delta > 0 ? '+' : '') + r.share_delta + ' pts' : 'new to the set')
).join('\n');

const title = 'Organic market share - ' + cfg.your_domain + ' - ' + payload.checked_on;

const text = [
  title.toUpperCase(),
  '',
  'Peer set ' + payload.picked_by + '. Visit counts are DataForSEO estimates of',
  'what each domain\'s rankings are worth, not measured analytics.',
  '',
  pad('DOMAIN', 32) + pad('EST. VISITS', 14) + pad('SHARE', 9) + 'CHANGE',
  table,
  '',
  prose,
  '',
].join('\n');

const summary = rows.map((r) => r.domain + ' ' + r.share_pct + '%').join(', ');

return [{ json: { title, text, summary, checked_on: payload.checked_on, row_count: rows.length } }];

// single-item input: the report carries the whole peer set as one object.
// The Sheets append maps input fields to columns, so it needs one item per row.
// Handed the single object it would write one row whose columns are `title`,
// `text` and `summary`.
const payload = $('Gather The Lanes').first().json;

return (payload.rows || []).map((r) => ({
  json: {
    checked_on: String(r.checked_on),
    domain: String(r.domain),
    is_you: r.is_you ? 'yes' : 'no',
    visits: Number(r.visits) || 0,
    share_pct: Number(r.share_pct) || 0,
    keywords: Number(r.keywords) || 0,
  },
}));
